insert into public.deals (external_key, date, date_text, kind, asset_class, sport, target, target_kind, target_country, target_team_id, target_company_id, investor, investor_type, investor_company_id, investor_id, seller, stake_pct, amount, currency, valuation, valuation_currency, headline, summary, source_name, source_url, source)
  values ('deal:aston-villa-football-club:atairos:october-2024', null, 'October 2024', 'minority_investment', 'sports', 'football', 'Aston Villa Football Club', 'club', 'England', (select id from public.sports_teams where external_key = 'premier-league--aston-villa'), null, 'Atairos', 'private_equity', (select id from public.companies where lower(name) = lower('Atairos') limit 1), (select id from public.sports_investors where lower(name) = lower('Atairos') limit 1), 'V Sports (Nassef Sawiris and Wes Edens)', 31.1, null, null, null, null, 'Atairos increases its V Sports stake to about 31%', 'After its initial 20% entry, Atairos increased its position in V Sports to approximately 31.1% by October 2024, with V Sports subsequently described as owned by Sawiris (34%), Edens (34%) and Atairos (32%). Terms of the increase were not disclosed in the sources found.', 'Wikipedia (V Sports)', 'https://en.wikipedia.org/wiki/V_Sports', 'web_research')
